SELECT A.TASK_ID taskId, A.BEAN_NAME beanName, A.TASK_NAME taskName, A.ORDERNO orderNo, A.STATUS status, A.CREATE_USER createUser, A.CREATE_TIME createTime, A.UPDATE_USER updateUser, A.UPDATE_TIME updateTime, A.RS rs, A.SYSTEMID systemId, B.LOCAL_PATH localRootPath, B.SERVERTYPE serverType, B.REMOTE_PATH remotePath, B.SERVERIP ip, B.SERVERPORT port, B.USERNAME userName, B.PASSWORD passWord FROM VAL_INTERF_TASK A LEFT JOIN VAL_INTERF_SERVER_INFO B ON B.RS = A.RS AND B.SYSTEMID = A.SYSTEMID WHERE A.STATUS = 'E' /**SERVER_INFO表添加状态标识 leipeng 20180922**/ AND B.STATUS = 'Y'
and A.ORDERNO in
#{item}
and A.RS = #{rs}
and A.RS = #{RS}
and A.SYSTEMID = #{systemId}
ORDER BY A.ORDERNO

SELECT DISTINCT A.ORDERNO orderNo FROM val_interf_define A WHERE 1=1
AND A.INTERF_E_NAME IN
#{item}
and A.ORDERNO in
#{item}
ORDER BY A.ORDERNO
